static bool
builtin_unreachable_bb_p (basic_block bb, vec<unsigned char> &cache)
{
  if (cache[bb->index])
    return cache[bb->index] - 1;
  gimple_stmt_iterator si;
  auto_vec <basic_block, 4> visited_bbs;
  bool ret = false;
  while (true)
    {
      bool empty_bb = true;
      visited_bbs.safe_push (bb);
      cache[bb->index] = 3;
      for (si = gsi_start_nondebug_bb (bb);
	   !gsi_end_p (si) && empty_bb;
	   gsi_next_nondebug (&si))
	{
	  if (gimple_code (gsi_stmt (si)) != GIMPLE_PREDICT
	      && !gimple_clobber_p (gsi_stmt (si))
	      && !gimple_nop_p (gsi_stmt (si)))
	    {
	      empty_bb = false;
	      break;
	    }
	}
      if (!empty_bb)
	break;
      else
	bb = single_succ_edge (bb)->dest;
      if (cache[bb->index])
	{
	  ret = cache[bb->index] == 3 ? false : cache[bb->index] - 1;
	  goto done;
	}
    }
  if (gimple_call_builtin_p (gsi_stmt (si), BUILT_IN_UNREACHABLE)
      || gimple_call_builtin_p (gsi_stmt (si), BUILT_IN_UNREACHABLE_TRAP))
    ret = true;
done:
  for (basic_block vbb:visited_bbs)
    cache[vbb->index] = (unsigned char)ret + 1;
  return ret;
}

static bool
guards_builtin_unreachable (basic_block bb, vec<unsigned char> &cache)
{
  edge_iterator ei;
  edge e;
  FOR_EACH_EDGE (e, ei, bb->succs)
    if (builtin_unreachable_bb_p (e->dest, cache))
      {
	if (dump_file && (dump_flags & TDF_DETAILS))
	  fprintf (dump_file,
		   "BB %i ends with conditional guarding __builtin_unreachable;"
		   " conditinal is unnecesary\n", bb->index);
	return true;
      }
  return false;
}

static int
make_edges_bb (basic_block bb, struct omp_region **pcur_region, int *pomp_index)
{
  gimple *last = *gsi_last_bb (bb);
  bool fallthru = false;
  int ret = 0;

  if (!last)
    return ret;

  switch (gimple_code (last))
    {
    case GIMPLE_GOTO:
      if (make_goto_expr_edges (bb))
	ret = 1;
      fallthru = false;
      break;
    case GIMPLE_RETURN:
      {
	edge e = make_edge (bb, EXIT_BLOCK_PTR_FOR_FN (cfun), 0);
	e->goto_locus = gimple_location (last);
	fallthru = false;
      }
      break;
    case GIMPLE_COND:
      make_cond_expr_edges (bb);
      fallthru = false;
      break;
    case GIMPLE_SWITCH:
      make_gimple_switch_edges (as_a <gswitch *> (last), bb);
      fallthru = false;
      break;
    case GIMPLE_RESX:
      make_eh_edge (last);
      fallthru = false;
      break;
    case GIMPLE_EH_DISPATCH:
      fallthru = make_eh_dispatch_edges (as_a <geh_dispatch *> (last));
      break;

    case GIMPLE_CALL:
      /* If this function receives a nonlocal goto, then we need to
	 make edges from this call site to all the nonlocal goto
	 handlers.  */
      if (stmt_can_make_abnormal_goto (last))
	ret = 2;

      /* If this statement has reachable exception handlers, then
	 create abnormal edges to them.  */
      make_eh_edge (last);

      /* BUILTIN_RETURN is really a return statement.  */
      if (gimple_call_builtin_p (last, BUILT_IN_RETURN))
	{
	  make_edge (bb, EXIT_BLOCK_PTR_FOR_FN (cfun), 0);
	  fallthru = false;
	}
      /* Some calls are known not to return.  */
      else
	fallthru = !gimple_call_noreturn_p (last);
      break;

    case GIMPLE_ASSIGN:
      /* A GIMPLE_ASSIGN may throw internally and thus be considered
	 control-altering.  */
      if (is_ctrl_altering_stmt (last))
	make_eh_edge (last);
      fallthru = true;
      break;

    case GIMPLE_ASM:
      make_gimple_asm_edges (bb);
      fallthru = true;
      break;

    CASE_GIMPLE_OMP:
      fallthru = omp_make_gimple_edges (bb, pcur_region, pomp_index);
      break;

    case GIMPLE_TRANSACTION:
      {
        gtransaction *txn = as_a <gtransaction *> (last);
	tree label1 = gimple_transaction_label_norm (txn);
	tree label2 = gimple_transaction_label_uninst (txn);

	if (label1)
	  make_edge (bb, label_to_block (cfun, label1), EDGE_FALLTHRU);
	if (label2)
	  make_edge (bb, label_to_block (cfun, label2),
		     EDGE_TM_UNINSTRUMENTED | (label1 ? 0 : EDGE_FALLTHRU));

	tree label3 = gimple_transaction_label_over (txn);
	if (gimple_transaction_subcode (txn)
	    & (GTMA_HAVE_ABORT | GTMA_IS_OUTER))
	  make_edge (bb, label_to_block (cfun, label3), EDGE_TM_ABORT);

	fallthru = false;
      }
      break;

    default:
      gcc_assert (!stmt_ends_bb_p (last));
      fallthru = true;
      break;
    }

  if (fallthru)
    make_edge (bb, bb->next_bb, EDGE_FALLTHRU);

  return ret;
}

/* Return true if statement STMT within FUN could throw an exception.  */

bool
stmt_could_throw_p (function *fun, gimple *stmt)
{
  if (!flag_exceptions)
    return false;

  /* The only statements that can throw an exception are assignments,
     conditionals, calls, resx, and asms.  */
  switch (gimple_code (stmt))
    {
    case GIMPLE_RESX:
      return true;

    case GIMPLE_CALL:
      return !gimple_call_nothrow_p (as_a <gcall *> (stmt));

    case GIMPLE_COND:
      {
	if (fun && !fun->can_throw_non_call_exceptions)
	  return false;
	gcond *cond = as_a <gcond *> (stmt);
	tree lhs = gimple_cond_lhs (cond);
	return operation_could_trap_p (gimple_cond_code (cond),
				       FLOAT_TYPE_P (TREE_TYPE (lhs)),
				       false, NULL_TREE);
      }

    case GIMPLE_ASSIGN:
      if ((fun && !fun->can_throw_non_call_exceptions)
	  || gimple_clobber_p (stmt))
        return false;
      return stmt_could_throw_1_p (as_a <gassign *> (stmt));

    case GIMPLE_ASM:
      if (fun && !fun->can_throw_non_call_exceptions)
        return false;
      return gimple_asm_volatile_p (as_a <gasm *> (stmt));

    default:

static void
find_necessary_statements (struct cgraph_node *node)
{
  struct function *my_function = DECL_STRUCT_FUNCTION (node->decl);
  auto_vec<unsigned char, 10> cache;
  basic_block bb;
  auto_vec<gimple *> worklist;

  cache.safe_grow_cleared (last_basic_block_for_fn (cfun));
  /* Mark all obviously necessary statements.  */
  FOR_EACH_BB_FN (bb, my_function)
    {
      for (gimple_stmt_iterator gsi = gsi_start_phis (bb);
	   !gsi_end_p (gsi); gsi_next (&gsi))
	gimple_set_plf (gsi_stmt (gsi), STMT_NECESSARY, false);

      for (gimple_stmt_iterator bsi = gsi_start_bb (bb); !gsi_end_p (bsi);
	   gsi_next_nondebug (&bsi))
	{
	  gimple *stmt = gsi_stmt (bsi);

	  gimple_set_plf (stmt, STMT_NECESSARY, false);
	  if (gimple_has_side_effects (stmt)
	      || (is_ctrl_stmt (stmt)
		  && (gimple_code (stmt) != GIMPLE_COND
		      || !guards_builtin_unreachable (bb, cache)))
	      || gimple_store_p (stmt)
	      || gimple_code (stmt) == GIMPLE_ASM)
	    mark_stmt_necessary (stmt, worklist);
	}
    }
  while (worklist.length () > 0)
    {
      gimple *stmt = worklist.pop ();

      if (dump_file && (dump_flags & TDF_DETAILS))
	{
	  fprintf (dump_file, "processing: ");
	  print_gimple_stmt (dump_file, stmt, 0, TDF_SLIM);
	  fprintf (dump_file, "\n");
	}
      if (gimple_code (stmt) == GIMPLE_PHI)
	for (unsigned int k = 0; k < gimple_phi_num_args (stmt); k++)
	  {
	    tree arg = PHI_ARG_DEF (stmt, k);

	    if (TREE_CODE (arg) == SSA_NAME)
	      mark_operand_necessary (arg, worklist);
	  }
      else
	{
	  ssa_op_iter iter;
	  tree use;

	  FOR_EACH_SSA_TREE_OPERAND (use, stmt, iter, SSA_OP_USE)
	    mark_operand_necessary (use, worklist);
	}
    }
}
